package com.example.booking.service.impl;
import com.example.booking.dto.auth.*; import com.example.booking.security.JwtService; import com.example.booking.service.AuthService; import lombok.RequiredArgsConstructor; import org.springframework.security.authentication.*; import org.springframework.security.core.userdetails.UserDetails; import org.springframework.stereotype.Service;
@Service @RequiredArgsConstructor public class AuthServiceImpl implements AuthService { private final AuthenticationManager auth; private final JwtService jwt; public LoginResponse login(LoginRequest r){var a=auth.authenticate(new UsernamePasswordAuthenticationToken(r.username(),r.password()));String token=jwt.generateToken((UserDetails)a.getPrincipal());return new LoginResponse(token,"Bearer",jwt.getExpiration()/1000);} }
